import unreal,json
from pathlib import Path
material=unreal.load_asset('/Game/Materials/MM_Landscape')
rows=[]
for obj in unreal.ObjectIterator(unreal.MaterialExpressionLandscapeLayerBlend):
 if obj.get_outermost()!=material.get_outermost(): continue
 row={'node':obj.get_name(),'layers':[]}
 for layer in obj.get_editor_property('layers'):
  entry={}
  for name in ['LayerName','BlendType','ConstLayerInput','LayerInput']:
   try: entry[name]=str(layer.get_editor_property(name))
   except Exception as e: entry[name]=str(e)
  row['layers'].append(entry)
 try: row['input_names']=list(unreal.MaterialEditingLibrary.get_material_expression_input_names(obj))
 except Exception as e: row['input_names']=str(e)
 try: row['input_nodes']=[x.get_name() if x else None for x in unreal.MaterialEditingLibrary.get_inputs_for_material_expression(material,obj)]
 except Exception as e: row['input_nodes']=str(e)
 rows.append(row)
Path('C:/Users/tarik/Documents/GitHub/AGP/.scratch/splatmap-v2/manual-acceptance-20261024/49-debug-blend-connections.json').write_text(json.dumps(rows,indent=2))
print(json.dumps(rows,indent=2))
